const migrationSql="-- KOJAC Official Documents Reactivation V1.0.1\n-- NEW migration. Do not replay older migrations.\n-- Reactivates receipt + teacher_monthly_report as official numbered documents.\n-- Preserves legacy rows and existing numbering formats.\n\nupdate private.document_number_settings\nset is_active = true\nwhere document_type in ('receipt','teacher_monthly_report');\n\ncreate or replace function private.create_teacher_payroll_payment_record(\n  p_payroll_id uuid,\n  p_payment_date date,\n  p_payment_method text,\n  p_payment_reference text default null,\n  p_notes text default null,\n  p_actor uuid default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path to 'pg_catalog','public','private'\nas $function$\ndeclare\n  v_actor uuid:=coalesce(p_actor,auth.uid());\n  v_teacher uuid;\n  v_teacher_name text;\n  v_status text;\n  v_amount bigint;\n  v_profile jsonb;\n  v_period_start date;\n  v_period_end date;\n  v_existing private.teacher_payroll_payment_records%rowtype;\n  v_payment_method text:=coalesce(nullif(btrim(coalesce(p_payment_method,'')),''),'Transfer');\n  v_date date:=coalesce(p_payment_date,(current_timestamp at time zone 'Asia/Jakarta')::date);\n  v_bank_name text;\n  v_bank_account_name text;\n  v_bank_account_number text;\n  v_id uuid;\n  v_doc uuid;\n  v_receipt text;\nbegin\n  select py.teacher_id,py.status,py.net_amount,py.profile_snapshot,py.period_start,py.period_end,\n         coalesce(nullif(btrim(pr.full_name),''),nullif(btrim(pr.nickname),''),'Pengajar KOJAC')\n  into v_teacher,v_status,v_amount,v_profile,v_period_start,v_period_end,v_teacher_name\n  from private.teacher_payrolls py\n  left join public.profiles pr on pr.user_id=py.teacher_id\n  where py.id=p_payroll_id\n  for update of py;\n\n  if v_teacher is null then raise exception 'payroll_not_found'; end if;\n\n  select * into v_existing\n  from private.teacher_payroll_payment_records\n  where payroll_id=p_payroll_id;\n\n  if found then\n    if v_existing.receipt_number is null then\n      select x.document_id,x.document_number into v_doc,v_receipt\n      from private.issue_document_number(\n        'receipt',\n        v_existing.payment_date,\n        'teacher_payroll:' || p_payroll_id::text,\n        'Kwitansi Honor ' || v_teacher_name,\n        'Honor periode ' || v_period_start::text || ' s.d. ' || v_period_end::text,\n        jsonb_build_object(\n          'payroll_id',p_payroll_id,\n          'teacher_id',v_teacher,\n          'payment_id',v_existing.id,\n          'payment_date',v_existing.payment_date,\n          'amount',v_existing.amount\n        ),\n        v_actor\n      ) x;\n\n      update private.teacher_payroll_payment_records\n      set receipt_number=v_receipt,receipt_document_id=v_doc\n      where id=v_existing.id;\n    else\n      v_receipt:=v_existing.receipt_number;\n    end if;\n\n    return jsonb_build_object(\n      'payment_id',v_existing.id,\n      'receipt_number',v_receipt,\n      'already_recorded',true\n    );\n  end if;\n\n  if v_status not in('finalized','paid') then raise exception 'payroll_not_finalized'; end if;\n  if v_amount<=0 then raise exception 'invalid_payment_amount'; end if;\n\n  v_bank_name:=nullif(btrim(coalesce(v_profile->>'bank_name','')),'');\n  v_bank_account_name:=nullif(btrim(coalesce(v_profile->>'bank_account_name','')),'');\n  v_bank_account_number:=nullif(btrim(coalesce(v_profile->>'bank_account_number','')),'');\n\n  insert into private.teacher_payroll_payment_records(\n    payroll_id,teacher_id,payment_date,amount,payment_method,\n    bank_name,bank_account_name,bank_account_number,\n    payment_reference,notes,receipt_number,receipt_document_id,created_by\n  ) values(\n    p_payroll_id,v_teacher,v_date,v_amount,v_payment_method,\n    v_bank_name,v_bank_account_name,v_bank_account_number,\n    nullif(btrim(coalesce(p_payment_reference,'')),''),\n    nullif(btrim(coalesce(p_notes,'')),''),\n    null,null,v_actor\n  ) returning id into v_id;\n\n  select x.document_id,x.document_number into v_doc,v_receipt\n  from private.issue_document_number(\n    'receipt',\n    v_date,\n    'teacher_payroll:' || p_payroll_id::text,\n    'Kwitansi Honor ' || v_teacher_name,\n    'Honor periode ' || v_period_start::text || ' s.d. ' || v_period_end::text,\n    jsonb_build_object(\n      'payroll_id',p_payroll_id,\n      'teacher_id',v_teacher,\n      'payment_id',v_id,\n      'payment_date',v_date,\n      'amount',v_amount\n    ),\n    v_actor\n  ) x;\n\n  update private.teacher_payroll_payment_records\n  set receipt_number=v_receipt,receipt_document_id=v_doc\n  where id=v_id;\n\n  update private.teacher_payrolls\n  set status='paid',\n      paid_by=coalesce(v_actor,paid_by),\n      paid_at=coalesce(paid_at,now()),\n      paid_on=v_date,\n      payment_note=coalesce(\n        nullif(btrim(coalesce(p_payment_reference,'')),''),\n        nullif(btrim(coalesce(p_notes,'')),''),\n        payment_note\n      ),\n      updated_at=now()\n  where id=p_payroll_id;\n\n  return jsonb_build_object(\n    'payment_id',v_id,\n    'receipt_number',v_receipt,\n    'already_recorded',false\n  );\nend\n$function$;\n\ncreate or replace function public.finalize_management_teacher_monthly_report(p_monthly_report_id uuid)\nreturns text\nlanguage plpgsql\nsecurity definer\nset search_path to 'pg_catalog','public','private'\nas $function$\ndeclare\n  v_actor uuid:=auth.uid();\n  v_teacher uuid;\n  v_teacher_name text;\n  v_month date;\n  v_end date;\n  v_status text;\n  v_existing_number text;\n  v_existing_doc uuid;\n  v_finalized_at timestamptz;\n  v_snapshot jsonb;\n  v_doc uuid;\n  v_number text;\n  v_issue_date date;\nbegin\n  if v_actor is null then raise exception 'authentication_required'; end if;\n  if not private.teacher_payroll_is_management() then raise exception 'management_access_required'; end if;\n\n  select mr.teacher_id,mr.period_start,mr.period_end,mr.status,mr.report_number,mr.report_document_id,mr.finalized_at,\n         coalesce(nullif(btrim(pr.full_name),''),nullif(btrim(pr.nickname),''),'Pengajar KOJAC')\n  into v_teacher,v_month,v_end,v_status,v_existing_number,v_existing_doc,v_finalized_at,v_teacher_name\n  from private.teacher_monthly_reports mr\n  left join public.profiles pr on pr.user_id=mr.teacher_id\n  where mr.id=p_monthly_report_id\n  for update of mr;\n\n  if v_teacher is null then raise exception 'monthly_report_not_found'; end if;\n  if v_status='finalized' and v_existing_number is not null then return v_existing_number; end if;\n\n  if v_status<>'finalized' then\n    v_snapshot:=public.get_management_teacher_monthly_report(v_teacher,v_month);\n  end if;\n\n  v_issue_date:=coalesce((v_finalized_at at time zone 'Asia/Jakarta')::date,(current_timestamp at time zone 'Asia/Jakarta')::date);\n\n  select x.document_id,x.document_number into v_doc,v_number\n  from private.issue_document_number(\n    'teacher_monthly_report',\n    v_issue_date,\n    p_monthly_report_id::text,\n    'Laporan Bulanan Pengajar ' || v_teacher_name,\n    'Periode ' || v_month::text || ' s.d. ' || v_end::text,\n    jsonb_build_object(\n      'monthly_report_id',p_monthly_report_id,\n      'teacher_id',v_teacher,\n      'period_start',v_month,\n      'period_end',v_end\n    ),\n    v_actor\n  ) x;\n\n  update private.teacher_monthly_reports\n  set status='finalized',\n      snapshot=case when v_status='finalized' then snapshot else v_snapshot end,\n      report_number=v_number,\n      report_document_id=v_doc,\n      finalized_by=coalesce(finalized_by,v_actor),\n      finalized_at=coalesce(finalized_at,now()),\n      updated_at=now()\n  where id=p_monthly_report_id;\n\n  insert into public.admin_audit_logs(actor_id,action,target_user_id,details)\n  values(v_actor,'finalize_teacher_monthly_report',v_teacher,jsonb_build_object(\n    'monthly_report_id',p_monthly_report_id,\n    'official_document_number',true,\n    'report_number',v_number\n  ));\n\n  return v_number;\nend\n$function$;\n\n-- Safe repair for any records created while these document types were inactive.\ndo $block$\ndeclare r record; v_doc uuid; v_number text; v_name text;\nbegin\n  for r in\n    select pr.id payment_id,pr.payroll_id,pr.teacher_id,pr.payment_date,pr.amount,\n           py.period_start,py.period_end\n    from private.teacher_payroll_payment_records pr\n    join private.teacher_payrolls py on py.id=pr.payroll_id\n    where pr.receipt_number is null\n  loop\n    select coalesce(nullif(btrim(p.full_name),''),nullif(btrim(p.nickname),''),'Pengajar KOJAC')\n      into v_name from public.profiles p where p.user_id=r.teacher_id;\n    v_name:=coalesce(v_name,'Pengajar KOJAC');\n\n    select x.document_id,x.document_number into v_doc,v_number\n    from private.issue_document_number(\n      'receipt',r.payment_date,'teacher_payroll:'||r.payroll_id::text,\n      'Kwitansi Honor '||v_name,\n      'Honor periode '||r.period_start::text||' s.d. '||r.period_end::text,\n      jsonb_build_object('payroll_id',r.payroll_id,'teacher_id',r.teacher_id,'payment_id',r.payment_id,'payment_date',r.payment_date,'amount',r.amount),\n      null\n    ) x;\n\n    update private.teacher_payroll_payment_records\n    set receipt_number=v_number,receipt_document_id=v_doc\n    where id=r.payment_id and receipt_number is null;\n  end loop;\nend\n$block$;\n\ndo $block$\ndeclare r record; v_doc uuid; v_number text; v_name text; v_issue_date date;\nbegin\n  for r in\n    select id,teacher_id,period_start,period_end,finalized_at\n    from private.teacher_monthly_reports\n    where status='finalized' and report_number is null\n  loop\n    select coalesce(nullif(btrim(p.full_name),''),nullif(btrim(p.nickname),''),'Pengajar KOJAC')\n      into v_name from public.profiles p where p.user_id=r.teacher_id;\n    v_name:=coalesce(v_name,'Pengajar KOJAC');\n    v_issue_date:=coalesce((r.finalized_at at time zone 'Asia/Jakarta')::date,(current_timestamp at time zone 'Asia/Jakarta')::date);\n\n    select x.document_id,x.document_number into v_doc,v_number\n    from private.issue_document_number(\n      'teacher_monthly_report',v_issue_date,r.id::text,\n      'Laporan Bulanan Pengajar '||v_name,\n      'Periode '||r.period_start::text||' s.d. '||r.period_end::text,\n      jsonb_build_object('monthly_report_id',r.id,'teacher_id',r.teacher_id,'period_start',r.period_start,'period_end',r.period_end),\n      null\n    ) x;\n\n    update private.teacher_monthly_reports\n    set report_number=v_number,report_document_id=v_doc,updated_at=now()\n    where id=r.id and report_number is null;\n  end loop;\nend\n$block$;\n";

const NEW_FILES={
  'src/pages/HonorReceiptPage.tsx': "import { useEffect, useMemo, useState } from 'react';\nimport { ArrowLeft, Printer } from 'lucide-react';\nimport { Navigate, useParams } from 'react-router-dom';\nimport { supabase } from '../lib/supabase';\nimport { useAuth } from '../state/AuthContext';\nimport '../honor-receipt.css';\n\ntype PayrollLine = {\n  line_id:string;\n  activity_label:string;\n  class_name:string;\n  duration_minutes:number;\n  amount:number;\n};\n\ntype Payment = {\n  payment_id:string;\n  payment_date:string;\n  amount:number;\n  payment_method:string;\n  bank_name:string|null;\n  bank_account_name:string|null;\n  bank_account_number:string|null;\n  payment_reference:string|null;\n  notes:string|null;\n  receipt_number:string|null;\n  created_at:string;\n};\n\ntype Detail = {\n  payroll:{\n    payroll_id:string;\n    teacher_id:string;\n    period_start:string;\n    period_end:string;\n    status:'draft'|'finalized'|'paid';\n    base_amount:number;\n    additions_amount:number;\n    deductions_amount:number;\n    net_amount:number;\n    total_sessions:number;\n    total_minutes:number;\n    profile_snapshot:Record<string,string|null>;\n    paid_on:string|null;\n    slip_number:string|null;\n  };\n  payment:Payment|null;\n  lines:PayrollLine[];\n};\n\nconst rupiah = new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0});\n\nfunction fmtDate(value:string|null|undefined){\n  if(!value)return '—';\n  const d=new Date(`${value}T00:00:00+07:00`);\n  return new Intl.DateTimeFormat('id-ID',{\n    day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Jakarta',\n  }).format(d);\n}\n\nfunction money(value:number){\n  return `Rp. ${Math.round(Number(value||0)).toLocaleString('id-ID')},-`;\n}\n\nconst words=['','satu','dua','tiga','empat','lima','enam','tujuh','delapan','sembilan','sepuluh','sebelas'];\nfunction spell(value:number):string{\n  const n=Math.floor(Math.abs(value));\n  if(n<12)return words[n];\n  if(n<20)return `${spell(n-10)} belas`;\n  if(n<100)return `${spell(Math.floor(n/10))} puluh ${spell(n%10)}`.trim();\n  if(n<200)return `seratus ${spell(n-100)}`.trim();\n  if(n<1000)return `${spell(Math.floor(n/100))} ratus ${spell(n%100)}`.trim();\n  if(n<2000)return `seribu ${spell(n-1000)}`.trim();\n  if(n<1_000_000)return `${spell(Math.floor(n/1000))} ribu ${spell(n%1000)}`.trim();\n  if(n<1_000_000_000)return `${spell(Math.floor(n/1_000_000))} juta ${spell(n%1_000_000)}`.trim();\n  return String(n);\n}\nfunction sentence(value:string){\n  return value?value.charAt(0).toUpperCase()+value.slice(1):value;\n}\n\nfunction duration(minutes:number){\n  const h=Math.floor((minutes||0)/60),m=(minutes||0)%60;\n  return h?(m?`${h} jam ${m} menit`:`${h} jam`):`${m} menit`;\n}\n\nexport function HonorReceiptPage(){\n  const {payrollId}=useParams();\n  const {loading:authLoading}=useAuth();\n  const [detail,setDetail]=useState<Detail|null>(null);\n  const [loading,setLoading]=useState(true);\n  const [error,setError]=useState('');\n\n  useEffect(()=>{\n    if(!payrollId)return;\n    let active=true;\n    void supabase.rpc('get_teacher_payroll_detail',{p_payroll_id:payrollId}).then(({data,error:e})=>{\n      if(!active)return;\n      if(e){\n        console.error(e);\n        setError('Kwitansi honor tidak dapat dimuat.');\n      }else{\n        const next=data as Detail;\n        if(!next?.payment?.receipt_number){\n          setError('Kwitansi belum tersedia. Pembayaran honor belum tercatat.');\n        }else{\n          setDetail(next);\n        }\n      }\n      setLoading(false);\n    });\n    return()=>{active=false;};\n  },[payrollId]);\n\n  const classSummary=useMemo(()=>{\n    const names=new Set((detail?.lines??[]).map(x=>x.class_name).filter(Boolean));\n    return [...names].join(', ')||'Kelas KOJAC';\n  },[detail]);\n\n  if(authLoading||loading)return <div className=\"full-center\">Memuat kwitansi honor…</div>;\n  if(!payrollId)return <Navigate to=\"/\" replace/>;\n  if(error||!detail)return <div className=\"full-center\">{error||'Kwitansi tidak ditemukan.'}</div>;\n\n  const p=detail.payroll;\n  const payment=detail.payment!;\n  const profile=p.profile_snapshot||{};\n  const teacherName=String(profile.full_name||'Pengajar KOJAC');\n  const accountName=payment.bank_account_name||profile.bank_account_name||teacherName;\n  const accountNumber=payment.bank_account_number||profile.bank_account_number||'—';\n  const bankName=payment.bank_name||profile.bank_name||'—';\n\n  return <div className=\"honor-receipt-screen\">\n    <div className=\"honor-receipt-toolbar\">\n      <button type=\"button\" onClick={()=>window.history.back()}><ArrowLeft size={16}/> Kembali</button>\n      <button type=\"button\" onClick={()=>window.print()}><Printer size={16}/> Cetak / Simpan PDF</button>\n    </div>\n\n    <main className=\"honor-receipt-document\">\n      <section className=\"honor-receipt-page\">\n        <div className=\"honor-receipt-accent top\"/>\n        <div className=\"honor-receipt-accent bottom\"/>\n        <img className=\"honor-receipt-watermark\" src=\"/brand/kojac-symbol.png\" alt=\"\"/>\n\n        <header className=\"honor-receipt-header\">\n          <div className=\"honor-receipt-brand\">\n            <img src=\"/brand/kojac-symbol.png\" alt=\"\"/>\n            <div><strong>KOJAC</strong><span>Kuuhaku Online Japanese Class</span></div>\n          </div>\n          <div className=\"honor-receipt-title\">\n            <h1>KWITANSI</h1>\n            <strong>{payment.receipt_number}</strong>\n          </div>\n        </header>\n\n        <div className=\"honor-receipt-divider\"/>\n\n        <section className=\"honor-receipt-main\">\n          <div className=\"honor-receipt-row\">\n            <span>Sudah terima dari</span><b>:</b><strong>KOJAC — Kuuhaku Online Japanese Class</strong>\n          </div>\n          <div className=\"honor-receipt-row\">\n            <span>Nama Penerima</span><b>:</b><strong>{teacherName}</strong>\n          </div>\n          <div className=\"honor-receipt-row is-amount\">\n            <span>Uang Sejumlah</span><b>:</b><strong>{money(payment.amount)}</strong>\n          </div>\n          <div className=\"honor-receipt-row\">\n            <span>Terbilang</span><b>:</b><em>{sentence(spell(payment.amount))} rupiah</em>\n          </div>\n          <div className=\"honor-receipt-row\">\n            <span>Untuk Pembayaran</span><b>:</b>\n            <strong>Honor mengajar periode {fmtDate(p.period_start)} – {fmtDate(p.period_end)}</strong>\n          </div>\n          <div className=\"honor-receipt-row\">\n            <span>Kelas</span><b>:</b><span>{classSummary}</span>\n          </div>\n          <div className=\"honor-receipt-row\">\n            <span>Total Sesi / Durasi</span><b>:</b><span>{p.total_sessions} sesi · {duration(p.total_minutes)}</span>\n          </div>\n          <div className=\"honor-receipt-row\">\n            <span>No. Slip Honor</span><b>:</b><span>{p.slip_number||'—'}</span>\n          </div>\n        </section>\n\n        <section className=\"honor-receipt-payment\">\n          <h2>INFORMASI PEMBAYARAN</h2>\n          <div className=\"honor-receipt-payment-grid\">\n            <div><span>Tanggal Pembayaran</span><strong>{fmtDate(payment.payment_date)}</strong></div>\n            <div><span>Metode</span><strong>{payment.payment_method}</strong></div>\n            <div><span>Bank</span><strong>{bankName}</strong></div>\n            <div><span>Nama Rekening</span><strong>{accountName}</strong></div>\n            <div><span>Nomor Rekening</span><strong>{accountNumber}</strong></div>\n            <div><span>Referensi</span><strong>{payment.payment_reference||'—'}</strong></div>\n          </div>\n          {payment.notes&&<p className=\"honor-receipt-note\">Catatan: {payment.notes}</p>}\n        </section>\n\n        <section className=\"honor-receipt-sign\">\n          <div>\n            <span>{fmtDate(payment.payment_date)}</span>\n            <strong>KOJAC</strong>\n            <div className=\"honor-receipt-sign-space\"/>\n            <b>Manajemen KOJAC</b>\n          </div>\n          <div className=\"honor-receipt-stamp\">\n            <img src=\"/brand/kojac-symbol.png\" alt=\"\"/>\n          </div>\n        </section>\n\n        <footer className=\"honor-receipt-footer\">\n          <span>空白オンライン日本語クラス</span>\n          <strong>Kuuhaku Online Japanese Class</strong>\n          <small>一緒に一生懸命勉強しましょう！</small>\n        </footer>\n      </section>\n    </main>\n  </div>;\n}\n",
  'src/honor-receipt.css': "@page{size:A4;margin:0}\nhtml,body{print-color-adjust:exact;-webkit-print-color-adjust:exact}\n.honor-receipt-screen{min-height:100vh;background:#ece7e8;padding:24px}\n.honor-receipt-toolbar{width:210mm;max-width:100%;margin:0 auto 14px;display:flex;justify-content:space-between}\n.honor-receipt-toolbar button{display:inline-flex;align-items:center;gap:7px;border:1px solid #d7c9cc;border-radius:9px;background:#fff;color:#5e464d;padding:9px 12px;font-weight:800;cursor:pointer}\n.honor-receipt-document{display:grid;justify-content:center}\n.honor-receipt-page{position:relative;width:210mm;height:297mm;overflow:hidden;background:#fff;color:#171214;font-family:Arial,Helvetica,sans-serif;box-sizing:border-box;padding:20mm 18mm 24mm}\n.honor-receipt-accent{position:absolute;width:180px;height:31px;background:#ef3239;transform:rotate(-45deg);z-index:1}.honor-receipt-accent:before{content:\"\";position:absolute;left:42px;top:0;width:52px;height:31px;background:#76232c}.honor-receipt-accent.top{left:-63px;top:31px}.honor-receipt-accent.bottom{right:-63px;bottom:31px}\n.honor-receipt-watermark{position:absolute;left:50%;top:55%;width:65%;transform:translate(-50%,-50%);opacity:.035;filter:grayscale(1);z-index:0}\n.honor-receipt-header,.honor-receipt-main,.honor-receipt-payment,.honor-receipt-sign,.honor-receipt-footer,.honor-receipt-divider{position:relative;z-index:2}\n.honor-receipt-header{display:flex;justify-content:space-between;align-items:flex-start}.honor-receipt-brand{display:flex;align-items:center;gap:9px}.honor-receipt-brand img{width:54px;height:54px;object-fit:contain}.honor-receipt-brand div{display:grid}.honor-receipt-brand strong{font-size:27px;line-height:1}.honor-receipt-brand span{font-size:7px;margin-top:4px}.honor-receipt-title{text-align:right}.honor-receipt-title h1{margin:0 0 5px;color:#d40000;font-family:\"Times New Roman\",Times,serif;font-size:31pt}.honor-receipt-title>strong{font-size:10.5pt}\n.honor-receipt-divider{height:2px;background:#202020;margin:11mm 0 13mm}\n.honor-receipt-main{display:grid;gap:5mm;font-size:12.5pt}.honor-receipt-row{display:grid;grid-template-columns:48mm 6mm 1fr;align-items:start;min-height:7mm}.honor-receipt-row>span:first-child{font-weight:700}.honor-receipt-row.is-amount strong{font-size:18pt;color:#861e32}.honor-receipt-row em{font-family:\"Times New Roman\",Times,serif;font-size:13pt}\n.honor-receipt-payment{margin-top:16mm;border:1px solid #cdbfc2;border-radius:11px;padding:7mm 8mm;background:rgba(255,255,255,.78)}.honor-receipt-payment h2{margin:0 0 6mm;text-align:center;font-size:13pt;color:#781a2c}.honor-receipt-payment-grid{display:grid;grid-template-columns:1fr 1fr;gap:6mm 12mm}.honor-receipt-payment-grid div{border-bottom:1px solid #d9ced1;padding-bottom:3mm}.honor-receipt-payment-grid span,.honor-receipt-payment-grid strong{display:block}.honor-receipt-payment-grid span{font-size:8.5pt;color:#806b70}.honor-receipt-payment-grid strong{margin-top:1.5mm;font-size:11pt}.honor-receipt-note{margin:5mm 0 0;font-size:9.5pt;color:#69565b}\n.honor-receipt-sign{display:flex;justify-content:flex-end;align-items:center;gap:12mm;margin-top:18mm}.honor-receipt-sign>div:first-child{width:62mm;text-align:center;display:grid;gap:2mm;font-size:10pt}.honor-receipt-sign-space{height:19mm}.honor-receipt-stamp img{width:30mm;height:30mm;object-fit:contain;opacity:.18}\n.honor-receipt-footer{position:absolute;left:0;right:0;bottom:21mm;text-align:center;display:grid;gap:2px}.honor-receipt-footer span{font-size:12px}.honor-receipt-footer strong{font-size:14px}.honor-receipt-footer small{font-size:9px}\n@media print{html,body,#root{margin:0!important;padding:0!important;background:#fff!important;width:210mm!important}.sidebar,.mobile-nav-topbar,.honor-receipt-toolbar{display:none!important}.main{margin:0!important;padding:0!important}.honor-receipt-screen{margin:0!important;padding:0!important;background:#fff!important}.honor-receipt-page{width:210mm!important;height:297mm!important;margin:0!important}}\n@media(max-width:850px){.honor-receipt-screen{padding:10px;overflow:auto}.honor-receipt-toolbar{min-width:700px}.honor-receipt-document{justify-content:start}}\n",
  'src/pages/ManagementTeacherMonthlyReportPage.tsx': "import { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  CalendarDays,\n  CheckCircle2,\n  Clock3,\n  FileCheck2,\n  FileText,\n  Printer,\n  RefreshCw,\n  Save,\n  Users,\n} from 'lucide-react';\nimport { Link, Navigate } from 'react-router-dom';\nimport { supabase } from '../lib/supabase';\nimport { useAuth } from '../state/AuthContext';\nimport type { AppRole } from '../types';\nimport '../teacher-monthly-report.css';\n\nconst MANAGEMENT_ROLES=new Set<AppRole>(['administrator','manager','co_founder','founder']);\n\ntype TeacherRow={\n  teacher_id:string;\n  teacher_name:string;\n  approved_count:number;\n  approved_minutes:number;\n  payroll_id:string|null;\n  payroll_status:string|null;\n  net_amount:number|null;\n};\n\ntype Overview={rows:TeacherRow[]};\n\ntype MonthlyPayload={\n  teacher:{teacher_id:string;teacher_name:string;team_name:string|null;domicile:string|null;phone:string|null};\n  period_start:string;\n  period_end:string;\n  summary:{report_count:number;approved_count:number;submitted_count:number;revision_count:number;class_count:number;approved_minutes:number};\n  live_summary:{live_session_count:number;ended_live_sessions:number;student_attendance_records:number;unique_students_seen:number;late_records:number;total_student_seconds:number};\n  classes:Array<{class_id:string;class_name:string;class_code:string|null;report_count:number;approved_count:number;submitted_count:number;revision_count:number;approved_minutes:number}>;\n  reports:Array<{report_id:string;class_id:string;class_name:string;class_code:string|null;teacher_name:string;report_date:string;starts_at:string;ends_at:string;duration_minutes:number;material_summary:string;assignment_summary:string;next_plan:string;evaluation_notes:string|null;review_status:'submitted'|'approved'|'revision';review_note:string|null;reviewed_at:string|null}>;\n  payroll:null|{payroll_id:string;status:string;base_amount:number;additions_amount:number;deductions_amount:number;net_amount:number;total_sessions:number;total_minutes:number;slip_number:string|null;paid_on:string|null};\n  saved_report:null|{monthly_report_id:string;status:'draft'|'finalized';report_number:string|null;management_notes:string|null;generated_at:string;finalized_at:string|null};\n};\n\nconst rupiah=new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0});\nfunction monthNow(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}\nfunction fmtDate(v:string){const d=new Date(`${v}T00:00:00+07:00`);return new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Jakarta'}).format(d);}\nfunction duration(m:number){const h=Math.floor((m||0)/60),r=(m||0)%60;return h?(r?`${h} jam ${r} menit`:`${h} jam`):`${r} menit`;}\nfunction statusLabel(s:string){if(s==='approved')return 'Approved';if(s==='revision')return 'Perlu Revisi';return 'Menunggu Review';}\n\nexport function ManagementTeacherMonthlyReportPage(){\n  const {role,loading:authLoading}=useAuth();\n  const canManage=Boolean(role&&MANAGEMENT_ROLES.has(role));\n  const [month,setMonth]=useState(monthNow);\n  const [teachers,setTeachers]=useState<TeacherRow[]>([]);\n  const [teacherId,setTeacherId]=useState('');\n  const [payload,setPayload]=useState<MonthlyPayload|null>(null);\n  const [notes,setNotes]=useState('');\n  const [loading,setLoading]=useState(true);\n  const [busy,setBusy]=useState(false);\n  const [message,setMessage]=useState('');\n\n  const loadTeachers=useCallback(async()=>{\n    if(!canManage)return;\n    const {data,error}=await supabase.rpc('get_management_honor_overview',{p_month:`${month}-01`});\n    if(error){console.error(error);setMessage('Daftar pengajar belum dapat dimuat.');return;}\n    const rows=((data as Overview)?.rows??[]);\n    setTeachers(rows);\n    setTeacherId(current=>current&&rows.some(x=>x.teacher_id===current)?current:(rows[0]?.teacher_id??''));\n  },[canManage,month]);\n\n  const loadReport=useCallback(async()=>{\n    if(!teacherId)return;\n    setLoading(true);setMessage('');\n    const {data,error}=await supabase.rpc('get_management_teacher_monthly_report',{\n      p_teacher_id:teacherId,p_month:`${month}-01`,\n    });\n    if(error){console.error(error);setMessage('Laporan bulanan belum dapat dimuat.');setPayload(null);}\n    else{\n      const next=data as MonthlyPayload;\n      setPayload(next);\n      setNotes(next.saved_report?.management_notes??'');\n    }\n    setLoading(false);\n  },[teacherId,month]);\n\n  useEffect(()=>{if(!authLoading&&canManage)void loadTeachers();},[authLoading,canManage,loadTeachers]);\n  useEffect(()=>{if(teacherId)void loadReport();},[teacherId,loadReport]);\n\n  async function saveDraft(){\n    if(!teacherId)return;\n    setBusy(true);setMessage('');\n    const {data,error}=await supabase.rpc('save_management_teacher_monthly_report',{\n      p_teacher_id:teacherId,p_month:`${month}-01`,p_management_notes:notes.trim()||null,\n    });\n    setBusy(false);\n    if(error){console.error(error);setMessage('Draft laporan bulanan belum tersimpan.');return;}\n    setMessage(`Draft tersimpan.`);\n    await loadReport();\n    return data as string;\n  }\n\n  async function finalize(){\n    if(!payload)return;\n    let reportId=payload.saved_report?.monthly_report_id??null;\n    if(!reportId)reportId=await saveDraft()??null;\n    if(!reportId)return;\n    if(!window.confirm('Finalkan laporan bulanan? Snapshot dan nomor laporan akan dikunci.'))return;\n    setBusy(true);setMessage('');\n    const {data,error}=await supabase.rpc('finalize_management_teacher_monthly_report',{p_monthly_report_id:reportId});\n    setBusy(false);\n    if(error){console.error(error);setMessage('Laporan bulanan belum dapat difinalkan.');return;}\n    setMessage(`Laporan final: ${String(data)}`);\n    await loadReport();\n  }\n\n  if(authLoading)return <div className=\"full-center\">Memuat KOJAC LMS…</div>;\n  if(!canManage)return <Navigate to=\"/\" replace/>;\n\n  const p=payload;\n  return <div className=\"page monthly-report-page\">\n    <header className=\"monthly-report-header\">\n      <div><p className=\"eyebrow\">MANAJEMEN KOJAC</p><h1><FileCheck2 size={30}/> Laporan Bulanan Pengajar</h1><p>Rekap resmi aktivitas mengajar, review, kelas, kehadiran live, dan honor per periode.</p></div>\n      <div className=\"monthly-report-filters\">\n        <label><span>Periode</span><input type=\"month\" value={month} onChange={e=>setMonth(e.target.value)}/></label>\n        <label><span>Pengajar</span><select value={teacherId} onChange={e=>setTeacherId(e.target.value)}>{teachers.map(t=><option key={t.teacher_id} value={t.teacher_id}>{t.teacher_name}</option>)}</select></label>\n      </div>\n    </header>\n\n    {message&&<div className=\"monthly-notice\">{message}</div>}\n    {loading||!p?<div className=\"monthly-empty\">Memuat laporan bulanan…</div>:<>\n      <section className=\"monthly-summary\">\n        <article><FileText/><strong>{p.summary.approved_count}</strong><span>Laporan Approved</span></article>\n        <article><Clock3/><strong>{duration(p.summary.approved_minutes)}</strong><span>Durasi Mengajar</span></article>\n        <article><CalendarDays/><strong>{p.summary.class_count}</strong><span>Kelas</span></article>\n        <article><Users/><strong>{p.live_summary.unique_students_seen}</strong><span>Siswa Terdeteksi Live</span></article>\n      </section>\n\n      <section className=\"monthly-report-card\">\n        <div className=\"monthly-card-heading\">\n          <div><p className=\"eyebrow\">IDENTITAS</p><h2>{p.teacher.teacher_name}</h2><span>{p.teacher.team_name||'Pengajar KOJAC'} · {fmtDate(p.period_start)} – {fmtDate(p.period_end)}</span></div>\n          <div className=\"monthly-status-stack\">\n            <span className={`monthly-status is-${p.saved_report?.status??'none'}`}>\n              {p.saved_report?.status==='finalized'?'Final':p.saved_report?.status==='draft'?'Draft':'Belum disimpan'}\n            </span>\n            {p.saved_report?.report_number&&<strong>{p.saved_report.report_number}</strong>}\n          </div>\n        </div>\n\n        <div className=\"monthly-metrics-grid\">\n          <div><span>Total Laporan</span><strong>{p.summary.report_count}</strong></div>\n          <div><span>Menunggu Review</span><strong>{p.summary.submitted_count}</strong></div>\n          <div><span>Perlu Revisi</span><strong>{p.summary.revision_count}</strong></div>\n          <div><span>Live Session</span><strong>{p.live_summary.live_session_count}</strong></div>\n          <div><span>Catatan Kehadiran</span><strong>{p.live_summary.student_attendance_records}</strong></div>\n          <div><span>Terlambat</span><strong>{p.live_summary.late_records}</strong></div>\n        </div>\n      </section>\n\n      <section className=\"monthly-report-card\">\n        <div className=\"monthly-card-heading\"><div><p className=\"eyebrow\">KELAS</p><h2>Rekap per Kelas</h2></div></div>\n        <div className=\"monthly-table-scroll\"><table className=\"monthly-table\">\n          <thead><tr><th>Kelas</th><th>Laporan</th><th>Approved</th><th>Review</th><th>Revisi</th><th>Durasi</th></tr></thead>\n          <tbody>{p.classes.map(c=><tr key={c.class_id}><td><strong>{c.class_name}</strong><small>{c.class_code||''}</small></td><td>{c.report_count}</td><td>{c.approved_count}</td><td>{c.submitted_count}</td><td>{c.revision_count}</td><td>{duration(c.approved_minutes)}</td></tr>)}</tbody>\n        </table></div>\n      </section>\n\n      <section className=\"monthly-report-card\">\n        <div className=\"monthly-card-heading\"><div><p className=\"eyebrow\">PERTEMUAN</p><h2>Detail Laporan</h2></div><span>{p.reports.length} laporan</span></div>\n        <div className=\"monthly-session-list\">\n          {p.reports.map(r=><article key={r.report_id}>\n            <header><div><strong>{fmtDate(r.report_date)} · {r.class_name}</strong><span>{r.starts_at.slice(0,5)}–{r.ends_at.slice(0,5)} · {duration(r.duration_minutes)}</span></div><span className={`monthly-review is-${r.review_status}`}>{statusLabel(r.review_status)}</span></header>\n            <div className=\"monthly-session-grid\">\n              <div><span>Materi</span><p>{r.material_summary}</p></div>\n              <div><span>Tugas</span><p>{r.assignment_summary}</p></div>\n              <div><span>Rencana Berikutnya</span><p>{r.next_plan}</p></div>\n              <div><span>Evaluasi</span><p>{r.evaluation_notes||'—'}</p></div>\n            </div>\n          </article>)}\n        </div>\n      </section>\n\n      <section className=\"monthly-report-card\">\n        <div className=\"monthly-card-heading\"><div><p className=\"eyebrow\">HONOR</p><h2>Ringkasan Pembayaran</h2></div></div>\n        {p.payroll?<div className=\"monthly-payroll-grid\">\n          <div><span>Status</span><strong>{p.payroll.status}</strong></div>\n          <div><span>Sesi Dibayar</span><strong>{p.payroll.total_sessions}</strong></div>\n          <div><span>Durasi Payroll</span><strong>{duration(p.payroll.total_minutes)}</strong></div>\n          <div><span>Honor Bersih</span><strong>{rupiah.format(p.payroll.net_amount)}</strong></div>\n          <div><span>No. Slip</span><strong>{p.payroll.slip_number||'—'}</strong></div>\n        </div>:<div className=\"monthly-empty is-small\">Payroll periode ini belum tersedia.</div>}\n      </section>\n\n      <section className=\"monthly-report-card\">\n        <div className=\"monthly-card-heading\"><div><p className=\"eyebrow\">CATATAN</p><h2>Catatan Manajemen</h2></div></div>\n        <textarea rows={5} value={notes} disabled={p.saved_report?.status==='finalized'} onChange={e=>setNotes(e.target.value)} placeholder=\"Evaluasi bulanan, tindak lanjut, catatan kualitas pengajaran, atau informasi administratif.\"/>\n        <div className=\"monthly-actions\">\n          {p.saved_report?.monthly_report_id&&<Link className=\"monthly-secondary\" target=\"_blank\" to={`/laporan-pengajar-bulanan/${p.saved_report.monthly_report_id}`}><Printer size={15}/> Preview / Cetak</Link>}\n          {p.saved_report?.status!=='finalized'&&<button className=\"monthly-secondary\" disabled={busy} onClick={()=>void saveDraft()}><Save size={15}/> Simpan Draft</button>}\n          {p.saved_report?.status!=='finalized'&&<button className=\"monthly-primary\" disabled={busy} onClick={()=>void finalize()}><CheckCircle2 size={15}/> Finalkan Laporan</button>}\n          <button className=\"monthly-secondary\" disabled={busy} onClick={()=>void loadReport()}><RefreshCw size={15}/> Refresh Data</button>\n        </div>\n      </section>\n    </>}\n  </div>;\n}\n",
  'src/pages/TeacherMonthlyReportsPage.tsx': "import { useCallback, useEffect, useState } from 'react';\nimport { CalendarDays, FileText } from 'lucide-react';\nimport { Link, Navigate } from 'react-router-dom';\nimport { supabase } from '../lib/supabase';\nimport { useAuth } from '../state/AuthContext';\nimport type { AppRole } from '../types';\nimport '../teacher-monthly-report.css';\n\nconst TEACHING_ROLES=new Set<AppRole>(['pengajar','administrator','manager','co_founder','founder']);\ntype Row={monthly_report_id:string;period_start:string;period_end:string;report_number:string|null;finalized_at:string|null};\nfunction fmt(v:string){const d=new Date(`${v}T00:00:00+07:00`);return new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(d);}\n\nexport function TeacherMonthlyReportsPage(){\n  const {role,loading:authLoading}=useAuth();\n  const canTeach=Boolean(role&&TEACHING_ROLES.has(role));\n  const [rows,setRows]=useState<Row[]>([]);\n  const [loading,setLoading]=useState(true);\n  const [error,setError]=useState('');\n\n  const load=useCallback(async()=>{\n    setLoading(true);setError('');\n    const {data,error:e}=await supabase.rpc('get_my_teacher_monthly_reports');\n    if(e){console.error(e);setError('Laporan bulanan belum dapat dimuat.');}\n    else setRows((data??[]) as Row[]);\n    setLoading(false);\n  },[]);\n  useEffect(()=>{if(!authLoading&&canTeach)void load();},[authLoading,canTeach,load]);\n\n  if(authLoading)return <div className=\"full-center\">Memuat KOJAC LMS…</div>;\n  if(!canTeach)return <Navigate to=\"/\" replace/>;\n\n  return <div className=\"page monthly-report-page\">\n    <header className=\"monthly-report-header\"><div><p className=\"eyebrow\">PENGAJAR KOJAC</p><h1><FileText size={29}/> Laporan Bulanan Saya</h1><p>Laporan bulanan yang sudah difinalkan oleh Manajemen KOJAC.</p></div></header>\n    {error&&<div className=\"monthly-notice\">{error}</div>}\n    {loading?<div className=\"monthly-empty\">Memuat laporan…</div>:rows.length===0?<div className=\"monthly-empty\"><FileText size={28}/><h3>Belum ada laporan bulanan final.</h3></div>:<div className=\"teacher-monthly-list\">\n      {rows.map(r=><article key={r.monthly_report_id}>\n        <div className=\"teacher-monthly-period\"><CalendarDays size={19}/><div><strong>{fmt(r.period_start)} – {fmt(r.period_end)}</strong><span>{r.report_number||'Nomor belum tersedia'}</span></div></div>\n        <Link className=\"monthly-primary\" target=\"_blank\" to={`/laporan-pengajar-bulanan/${r.monthly_report_id}`}><FileText size={15}/> Lihat Laporan</Link>\n      </article>)}\n    </div>}\n  </div>;\n}\n",
  'src/pages/TeacherMonthlyReportPrintPage.tsx': "import { useEffect, useState } from 'react';\nimport { ArrowLeft, Printer } from 'lucide-react';\nimport { Link, Navigate, useParams } from 'react-router-dom';\nimport { supabase } from '../lib/supabase';\nimport { useAuth } from '../state/AuthContext';\nimport '../teacher-monthly-report-print.css';\n\ntype Detail={\n  monthly_report_id:string;teacher_id:string;period_start:string;period_end:string;status:string;\n  report_number:string|null;management_notes:string|null;generated_at:string;finalized_at:string|null;\n  snapshot:{\n    teacher:{teacher_id:string;teacher_name:string;team_name:string|null;domicile:string|null;phone:string|null};\n    summary:{report_count:number;approved_count:number;submitted_count:number;revision_count:number;class_count:number;approved_minutes:number};\n    live_summary:{live_session_count:number;ended_live_sessions:number;student_attendance_records:number;unique_students_seen:number;late_records:number;total_student_seconds:number};\n    classes:Array<{class_id:string;class_name:string;class_code:string|null;report_count:number;approved_count:number;submitted_count:number;revision_count:number;approved_minutes:number}>;\n    reports:Array<{report_id:string;class_name:string;report_date:string;starts_at:string;ends_at:string;duration_minutes:number;material_summary:string;assignment_summary:string;next_plan:string;evaluation_notes:string|null;review_status:string}>;\n    payroll:null|{status:string;net_amount:number;total_sessions:number;total_minutes:number;slip_number:string|null;paid_on:string|null};\n  };\n};\n\nconst rupiah=new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0});\nfunction fmt(v:string){const d=new Date(`${v}T00:00:00+07:00`);return new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(d);}\nfunction dur(m:number){const h=Math.floor((m||0)/60),r=(m||0)%60;return h?(r?`${h} jam ${r} menit`:`${h} jam`):`${r} menit`;}\n\nexport function TeacherMonthlyReportPrintPage(){\n  const {reportId}=useParams();\n  const {loading:authLoading}=useAuth();\n  const [detail,setDetail]=useState<Detail|null>(null);\n  const [loading,setLoading]=useState(true);\n  const [error,setError]=useState('');\n\n  useEffect(()=>{\n    if(!reportId)return;\n    let active=true;\n    void supabase.rpc('get_teacher_monthly_report_detail',{p_monthly_report_id:reportId}).then(({data,error:e})=>{\n      if(!active)return;\n      if(e){console.error(e);setError('Laporan bulanan tidak dapat dimuat.');}\n      else setDetail(data as Detail);\n      setLoading(false);\n    });\n    return()=>{active=false;};\n  },[reportId]);\n\n  if(authLoading||loading)return <div className=\"full-center\">Memuat laporan…</div>;\n  if(!reportId)return <Navigate to=\"/\" replace/>;\n  if(error||!detail)return <div className=\"full-center\">{error||'Laporan tidak ditemukan.'}</div>;\n\n  const s=detail.snapshot;\n  return <div className=\"monthly-print-screen\">\n    <div className=\"monthly-print-toolbar\">\n      <Link to=\"/\"><ArrowLeft size={15}/> Kembali</Link>\n      <button onClick={()=>window.print()}><Printer size={15}/> Cetak / Simpan PDF</button>\n    </div>\n\n    <main className=\"monthly-print-doc\">\n      <section className=\"monthly-print-page\">\n        <div className=\"monthly-print-accent top\"/>\n        <div className=\"monthly-print-accent bottom\"/>\n        <header className=\"monthly-print-header\">\n          <div><p>KOJAC</p><span>KUUHAKU ONLINE JAPANESE CLASS</span></div>\n          <div><h1>LAPORAN BULANAN PENGAJAR</h1><strong>{detail.report_number||'DRAFT'}</strong></div>\n        </header>\n\n        <div className=\"monthly-print-identity\">\n          <div><span>Nama</span><strong>{s.teacher.teacher_name}</strong></div>\n          <div><span>Team</span><strong>{s.teacher.team_name||'Pengajar KOJAC'}</strong></div>\n          <div><span>Periode</span><strong>{fmt(detail.period_start)} – {fmt(detail.period_end)}</strong></div>\n          <div><span>Status</span><strong>{detail.status==='finalized'?'Final':'Draft'}</strong></div>\n        </div>\n\n        <h2>RINGKASAN</h2>\n        <table><tbody>\n          <tr><td>Total Laporan</td><td>{s.summary.report_count}</td><td>Approved</td><td>{s.summary.approved_count}</td></tr>\n          <tr><td>Jumlah Kelas</td><td>{s.summary.class_count}</td><td>Durasi Mengajar Approved</td><td>{dur(s.summary.approved_minutes)}</td></tr>\n          <tr><td>Live Session</td><td>{s.live_summary.live_session_count}</td><td>Siswa Terdeteksi Live</td><td>{s.live_summary.unique_students_seen}</td></tr>\n          <tr><td>Catatan Terlambat</td><td>{s.live_summary.late_records}</td><td>Menunggu/Revisi</td><td>{s.summary.submitted_count+s.summary.revision_count}</td></tr>\n        </tbody></table>\n\n        <h2>REKAP PER KELAS</h2>\n        <table>\n          <thead><tr><th>Kelas</th><th>Laporan</th><th>Approved</th><th>Durasi</th></tr></thead>\n          <tbody>{s.classes.map(c=><tr key={c.class_id}><td>{c.class_name}</td><td>{c.report_count}</td><td>{c.approved_count}</td><td>{dur(c.approved_minutes)}</td></tr>)}</tbody>\n        </table>\n\n        {s.payroll&&<>\n          <h2>RINGKASAN HONOR</h2>\n          <table><tbody>\n            <tr><td>Status Payroll</td><td>{s.payroll.status}</td><td>No. Slip</td><td>{s.payroll.slip_number||'—'}</td></tr>\n            <tr><td>Sesi Dibayar</td><td>{s.payroll.total_sessions}</td><td>Honor Bersih</td><td>{rupiah.format(s.payroll.net_amount)}</td></tr>\n          </tbody></table>\n        </>}\n\n        <h2>CATATAN MANAJEMEN</h2>\n        <div className=\"monthly-print-notes\">{detail.management_notes||'Tidak ada catatan tambahan.'}</div>\n\n        <footer><span>空白オンライン日本語クラス</span><strong>Kuuhaku Online Japanese Class</strong><small>一緒に一生懸命勉強しましょう！</small></footer>\n      </section>\n\n      <section className=\"monthly-print-page monthly-print-sessions\">\n        <div className=\"monthly-print-accent top\"/>\n        <div className=\"monthly-print-accent bottom\"/>\n        <header className=\"monthly-print-header\"><div><p>KOJAC</p><span>KUUHAKU ONLINE JAPANESE CLASS</span></div><div><h1>DETAIL KEGIATAN MENGAJAR</h1><strong>{detail.report_number||'DRAFT'}</strong></div></header>\n        <table className=\"session-table\">\n          <thead><tr><th>Tanggal</th><th>Kelas / Waktu</th><th>Materi</th><th>Evaluasi</th></tr></thead>\n          <tbody>{s.reports.map(r=><tr key={r.report_id}><td>{fmt(r.report_date)}</td><td><strong>{r.class_name}</strong><br/>{r.starts_at.slice(0,5)}–{r.ends_at.slice(0,5)}<br/>{dur(r.duration_minutes)}</td><td>{r.material_summary}</td><td>{r.evaluation_notes||'—'}</td></tr>)}</tbody>\n        </table>\n        <footer><span>空白オンライン日本語クラス</span><strong>Kuuhaku Online Japanese Class</strong><small>一緒に一生懸命勉強しましょう！</small></footer>\n      </section>\n    </main>\n  </div>;\n}\n",
  'src/teacher-monthly-report.css': ".monthly-report-page{max-width:1500px;margin:0 auto;padding-bottom:56px}\n.monthly-report-header{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;margin-bottom:18px}.monthly-report-header h1{display:flex;align-items:center;gap:10px;margin:4px 0 6px;font-size:clamp(28px,3vw,42px)}.monthly-report-header p{margin:0;color:#7e6970}\n.monthly-report-filters{display:flex;gap:9px}.monthly-report-filters label{display:grid;gap:4px}.monthly-report-filters span{font-size:9px;font-weight:850;color:#755f65}.monthly-report-filters input,.monthly-report-filters select,.monthly-report-card textarea{border:1px solid #dfd2d5;border-radius:10px;background:#fff;padding:10px 11px;font:inherit;color:#2d2124}\n.monthly-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin-bottom:14px}.monthly-summary article{display:grid;grid-template-columns:auto 1fr;column-gap:10px;align-items:center;background:#fff;border:1px solid #eadfe1;border-radius:15px;padding:15px}.monthly-summary svg{grid-row:1/3;color:#8b1e33}.monthly-summary strong{font-size:22px}.monthly-summary span{font-size:10px;color:#816d73}\n.monthly-report-card{background:#fff;border:1px solid #e7dbde;border-radius:16px;padding:16px;margin-bottom:13px}.monthly-card-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:12px}.monthly-card-heading h2{margin:2px 0}.monthly-card-heading span{font-size:10px;color:#837077}\n.monthly-status-stack{text-align:right}.monthly-status{display:inline-flex;border-radius:999px;padding:5px 8px;background:#f2edef;color:#715b61;font-size:9px;font-weight:900}.monthly-status.is-finalized{background:#eaf6ef;color:#166534}.monthly-status.is-draft{background:#fff7ed;color:#9a3412}.monthly-status-stack strong{display:block;margin-top:5px;font-size:10px}\n.monthly-metrics-grid,.monthly-payroll-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.monthly-metrics-grid div,.monthly-payroll-grid div{padding:10px;background:#faf7f8;border-radius:10px}.monthly-metrics-grid span,.monthly-payroll-grid span{display:block;font-size:9px;color:#846f75}.monthly-metrics-grid strong,.monthly-payroll-grid strong{display:block;margin-top:3px}\n.monthly-table-scroll{overflow:auto}.monthly-table{width:100%;border-collapse:collapse;min-width:720px}.monthly-table th,.monthly-table td{padding:10px;border-bottom:1px solid #eee4e6;text-align:left}.monthly-table th{font-size:9px;text-transform:uppercase;color:#856f75}.monthly-table td{font-size:10px}.monthly-table td small{display:block;color:#8a757b}\n.monthly-session-list{display:grid;gap:9px}.monthly-session-list article{border:1px solid #eadfe1;border-radius:12px;padding:12px}.monthly-session-list header{display:flex;justify-content:space-between;gap:10px}.monthly-session-list header span{display:block;font-size:9px;color:#866f75}.monthly-review{padding:5px 7px!important;border-radius:999px;font-weight:900}.monthly-review.is-approved{background:#eaf6ef;color:#166534!important}.monthly-review.is-submitted{background:#fff7ed;color:#9a3412!important}.monthly-review.is-revision{background:#fff1f2;color:#9f1239!important}\n.monthly-session-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.monthly-session-grid div{background:#faf7f8;border-radius:9px;padding:9px}.monthly-session-grid span{font-size:8px;text-transform:uppercase;font-weight:900;color:#866f75}.monthly-session-grid p{margin:3px 0 0;font-size:10px;white-space:pre-wrap}\n.monthly-actions{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:8px;margin-top:11px}.monthly-primary,.monthly-secondary{display:inline-flex;align-items:center;gap:6px;border-radius:9px;padding:9px 11px;font-size:10px;font-weight:850;text-decoration:none;cursor:pointer}.monthly-primary{border:1px solid #861e32;background:#861e32;color:#fff}.monthly-secondary{border:1px solid #ddcfd2;background:#fff;color:#634b52}.monthly-notice{padding:10px 12px;border-radius:10px;background:#f7f2f3;color:#664e54;font-size:10px;margin-bottom:12px}.monthly-empty{text-align:center;padding:42px;color:#7e6870}.monthly-empty.is-small{padding:20px}\n.teacher-monthly-list{display:grid;gap:10px}.teacher-monthly-list article{display:flex;justify-content:space-between;align-items:center;gap:12px;background:#fff;border:1px solid #e8dcdf;border-radius:14px;padding:14px}.teacher-monthly-period{display:flex;align-items:center;gap:9px}.teacher-monthly-period span{display:block;font-size:9px;color:#857178;margin-top:3px}\n@media(max-width:900px){.monthly-report-header{align-items:flex-start;flex-direction:column}.monthly-report-filters{width:100%}.monthly-report-filters label{flex:1}.monthly-summary{grid-template-columns:1fr 1fr}.monthly-metrics-grid,.monthly-payroll-grid{grid-template-columns:1fr 1fr 1fr}}\n@media(max-width:600px){.monthly-report-filters{flex-direction:column}.monthly-summary{grid-template-columns:1fr}.monthly-metrics-grid,.monthly-payroll-grid,.monthly-session-grid{grid-template-columns:1fr}.teacher-monthly-list article{align-items:flex-start;flex-direction:column}}\n",
  'src/teacher-monthly-report-print.css': "@page{size:A4;margin:0}.monthly-print-screen{min-height:100vh;background:#eee7e8;padding:24px}.monthly-print-toolbar{max-width:794px;margin:0 auto 14px;display:flex;justify-content:space-between}.monthly-print-toolbar a,.monthly-print-toolbar button{display:inline-flex;align-items:center;gap:6px;border:1px solid #d7c9cc;border-radius:9px;background:#fff;color:#5d464d;padding:9px 11px;text-decoration:none;font-weight:800;cursor:pointer}.monthly-print-doc{display:grid;gap:24px;justify-content:center}.monthly-print-page{position:relative;width:794px;min-height:1123px;background:#fff;padding:52px 54px 82px;box-sizing:border-box;overflow:hidden;font-family:Arial,Helvetica,sans-serif;color:#111}.monthly-print-accent{position:absolute;width:170px;height:28px;background:#e92d34;transform:rotate(-45deg)}.monthly-print-accent.top{left:-60px;top:28px}.monthly-print-accent.bottom{right:-60px;bottom:28px}.monthly-print-header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px}.monthly-print-header>div:first-child p{margin:0;font-size:28px;font-weight:900}.monthly-print-header>div:first-child span{font-size:6px}.monthly-print-header>div:last-child{text-align:right}.monthly-print-header h1{margin:0 0 6px;color:#8b1e33;font-size:23px}.monthly-print-header strong{font-size:11px}.monthly-print-identity{display:grid;grid-template-columns:1fr 1fr;gap:7px 18px;margin-bottom:20px}.monthly-print-identity div{display:grid;grid-template-columns:80px 1fr;gap:8px;font-size:11px}.monthly-print-page h2{font-size:13px;margin:17px 0 6px;color:#781a2c}.monthly-print-page table{width:100%;border-collapse:collapse;font-size:10px}.monthly-print-page th,.monthly-print-page td{border:1px solid #222;padding:7px;text-align:left;vertical-align:top}.monthly-print-page th{background:#f7f2f3}.monthly-print-notes{min-height:80px;border:1px solid #222;padding:9px;font-size:10px;white-space:pre-wrap}.monthly-print-page footer{position:absolute;left:0;right:0;bottom:24px;text-align:center;display:grid;gap:2px}.monthly-print-page footer span{font-size:12px}.monthly-print-page footer strong{font-size:14px}.monthly-print-page footer small{font-size:9px}.session-table td:nth-child(1){width:15%}.session-table td:nth-child(2){width:20%}.session-table td:nth-child(3){width:32%}.session-table td:nth-child(4){width:33%}\n@media print{html,body,#root{margin:0!important;padding:0!important;width:210mm!important;background:#fff!important}.sidebar,.mobile-nav-topbar,.monthly-print-toolbar{display:none!important}.main{margin:0!important;padding:0!important}.monthly-print-screen{padding:0!important;background:#fff!important}.monthly-print-doc{display:block!important}.monthly-print-page{width:210mm!important;height:296mm!important;min-height:296mm!important;margin:0!important;box-shadow:none!important;break-after:page!important;page-break-after:always!important}.monthly-print-page:last-child{break-after:auto!important;page-break-after:auto!important}}\n@media(max-width:850px){.monthly-print-screen{padding:10px;overflow:auto}.monthly-print-toolbar{min-width:700px}}\n",
};

function fail(m){console.error(`\n[FAIL] ${m}`);process.exit(1);}
function file(rel){return path.resolve(root,rel);}
function exists(rel){return fs.existsSync(file(rel));}
function readRequired(rel){if(!exists(rel))fail(`Existing file wajib tidak ditemukan: ${rel}`);return fs.readFileSync(file(rel),'utf8');}
function readOptional(rel){return exists(rel)?fs.readFileSync(file(rel),'utf8'):null;}
function write(rel,c){const p=file(rel);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c,'utf8');if(!changed.includes(rel))changed.push(rel);}
function createIfMissing(rel,c){if(!exists(rel)){write(rel,c);created.push(rel);console.log(`[CREATE] ${rel}`);}else console.log(`[REUSE] ${rel}`);}
function patchRequired(rel,fn){const before=readRequired(rel);const after=fn(before);if(after!==before)write(rel,after);}
function patchIfPresent(rel,fn){const before=readOptional(rel);if(before===null)return false;const after=fn(before);if(after!==before)write(rel,after);return true;}
function count(src,needle){return src.split(needle).length-1;}
function replaceOnceRequired(src,oldText,newText,label){if(src.includes(newText))return src;if(!src.includes(oldText))fail(`Anchor tidak cocok: ${label}`);return src.replace(oldText,newText);}
function ensureSingle(src,needle,label){const n=count(src,needle);if(n!==1)fail(`${label} harus tepat 1, ditemukan ${n}.`);}

console.log('KOJAC Official Documents Reactivation V1.0.1');
console.log('Scope: receipt + teacher_monthly_report only. Slip Honor protected.');
if(!exists('package.json')||!exists('src'))fail('Jalankan installer dari root project KOJAC LMS.');

// A. EXISTING FILES: fitur management yang sudah terbukti ada pada actual flow.
const existingRequired=[
  'src/pages/ManagementHonorPaymentsPage.tsx',
  'src/pages/ManagementDocumentNumbersPage.tsx',
  'src/App.tsx',
  'src/components/AppShell.tsx'
];
for(const rel of existingRequired)readRequired(rel);

// B. NEW / REUSABLE LEGACY FILES: reuse jika ada, buat bila hilang.
for(const [rel,content] of Object.entries(NEW_FILES))createIfMissing(rel,content);

// C. OPTIONAL LEGACY FILES: absence tidak pernah menjadi blocker.
for(const rel of ['src/pages/TeacherHonorPage.tsx','src/pages/HonorReceiptDetailPage.tsx','src/pages/ReceiptPage.tsx']){
  if(exists(rel))console.log(`[OPTIONAL LEGACY] ${rel}`);
}

// Slip Honor: protected, never read-modify-written.
for(const rel of ['src/pages/HonorSlipPage.tsx','src/honor-slip.css']){
  if(exists(rel))console.log(`[PROTECTED] ${rel}`);
}

// Payment administration: official receipt number + entry point.
patchRequired('src/pages/ManagementHonorPaymentsPage.tsx', source=>{
  // Import safety.
  if(!source.includes('ReceiptText')){
    if(source.includes('  FileText,'))source=source.replace('  FileText,','  FileText,\n  ReceiptText,');
    else fail('Anchor import ReceiptText tidak ditemukan pada ManagementHonorPaymentsPage.tsx.');
  }
  if(!source.includes("import { Link, Navigate } from 'react-router-dom';") && !source.includes("import { Navigate, Link } from 'react-router-dom';")){
    if(source.includes("import { Navigate } from 'react-router-dom';"))source=source.replace("import { Navigate } from 'react-router-dom';","import { Link, Navigate } from 'react-router-dom';");
    else if(!source.includes("from 'react-router-dom'"))fail('Import react-router-dom tidak ditemukan pada Pembayaran Honor.');
  }

  if(!source.includes('receipt_number:string|null;')){
    const anchors=['  notes:string|null;\n','  payment_reference:string|null;\n'];
    const a=anchors.find(x=>source.includes(x));
    if(!a)fail('Anchor type receipt_number tidak ditemukan.');
    source=source.replace(a,`${a}  receipt_number:string|null;\n`);
  }

  if(!source.includes("String(row.receipt_number||'').toLowerCase().includes(needle)")){
    const a="      String(row.slip_number||'').toLowerCase().includes(needle) ||\n";
    if(source.includes(a))source=source.replace(a,`${a}      String(row.receipt_number||'').toLowerCase().includes(needle) ||\n`);
  }

  // RPC result should surface permanent receipt number.
  source=source.replace(
    `    const result=data as {already_recorded?:boolean};\n    setSelected(null);\n    setMessage(result.already_recorded?'Pembayaran sebelumnya sudah tercatat.':'Pembayaran honor tersimpan.');`,
    "    const result=data as {receipt_number?:string;already_recorded?:boolean};\n    setSelected(null);\n    const receipt=result.receipt_number?` · ${result.receipt_number}`:'';\n    setMessage(result.already_recorded?`Pembayaran sebelumnya sudah tercatat${receipt}.`:`Pembayaran honor tersimpan${receipt}.`);"
  );

  source=source.replace('Pusat administrasi pembayaran honor pengajar, rekening, slip, referensi transfer, dan status pembayaran.','Pusat administrasi pembayaran honor pengajar, rekening, slip, kwitansi resmi, referensi transfer, dan status pembayaran.');
  source=source.replace('placeholder="Cari pengajar / slip / referensi"','placeholder="Cari pengajar / slip / kwitansi / referensi"');
  source=source.replace('Setelah disimpan, payroll menjadi <strong>Dibayar</strong>. Nomor KWT tidak diterbitkan untuk pembayaran baru; record legacy tetap dipertahankan di audit trail.','Setelah disimpan, payroll menjadi <strong>Dibayar</strong> dan sistem menerbitkan nomor Kwitansi resmi secara otomatis.');

  // Receipt link: add only once, using known stable Slip button anchor.
  if(!source.includes('/honor/kwitansi/')){
    const slipLink="                    <Link className=\"honor-payment-secondary\" to={`/honor/slip/${row.payroll_id}`} target=\"_blank\">\n                      <FileText size={14}/> Slip\n                    </Link>";
    if(!source.includes(slipLink))fail('Anchor tombol Slip pada Pembayaran Honor tidak cocok.');
    source=source.replace(slipLink,slipLink+"\n                    {row.status==='paid'&&row.receipt_number&&\n                      <Link className=\"honor-payment-secondary\" to={`/honor/kwitansi/${row.payroll_id}`} target=\"_blank\" rel=\"noopener noreferrer\">\n                        <ReceiptText size={14}/> Kwitansi\n                      </Link>}");
  }

  if(source.includes('Nomor KWT tidak diterbitkan'))fail('Kebijakan KWT inactive masih tersisa pada Pembayaran Honor.');
  return source;
});

// Monthly management: support both current inactive wording and original official implementation.
patchIfPresent('src/pages/ManagementTeacherMonthlyReportPage.tsx', source=>{
  source=source.replace('Finalkan laporan bulanan? Snapshot laporan akan dikunci dan tidak dapat diedit lagi.','Finalkan laporan bulanan? Snapshot dan nomor laporan resmi akan dikunci.');
  source=source.replace(
    `    const {error}=await supabase.rpc('finalize_management_teacher_monthly_report',{p_monthly_report_id:reportId});\n    setBusy(false);\n    if(error){console.error(error);setMessage('Laporan bulanan belum dapat difinalkan.');return;}\n    setMessage('Laporan bulanan berhasil difinalkan.');`,
    "    const {data,error}=await supabase.rpc('finalize_management_teacher_monthly_report',{p_monthly_report_id:reportId});\n    setBusy(false);\n    if(error){console.error(error);setMessage('Laporan bulanan belum dapat difinalkan.');return;}\n    setMessage(`Laporan final · ${String(data||'nomor belum tersedia')}`);"
  );
  source=source.replace(`{p.saved_report?.report_number&&<strong>Nomor legacy: {p.saved_report.report_number}</strong>}`,`{p.saved_report?.report_number&&<strong>{p.saved_report.report_number}</strong>}`);
  if(source.includes('Nomor legacy:'))fail('Monthly management masih menandai nomor resmi sebagai legacy.');
  return source;
});

